/** The two custom marks Icon.svelte renders as inline SVG paths rather than a Hugeicons glyph. */
export type CustomIconName = keyof typeof iconPaths;

/**
 * Every standard glyph the panel uses, mapped to a Hugeicons free icon
 * inside Icon.svelte. Kept as an explicit union (rather than deriving it
 * from a lookup object) so this file stays free of any Hugeicons import —
 * only Icon.svelte needs to know which component each name maps to.
 */
export type StandardIconName =
  | "air"
  | "alt_route"
  | "arrow_back"
  | "arrow_downward"
  | "arrow_upward"
  | "bolt"
  | "build"
  | "check"
  | "check_circle"
  | "chevron_right"
  | "close"
  | "content_copy"
  | "delete"
  | "diamond"
  | "edit_square"
  | "expand_more"
  | "explore"
  | "group"
  | "hexagon"
  | "info"
  | "more_horiz"
  | "more_vert"
  | "open_in_new"
  | "public"
  | "refresh"
  | "settings"
  | "smart_toy"
  | "stop"
  | "subject"
  | "terminal"
  | "widgets";

/**
 * The name of any icon the panel can render. A union rather than `string`
 * so a typo is a `svelte-check` failure at build time instead of a blank
 * square at runtime.
 */
export type IconName = CustomIconName | StandardIconName;
